fun flattenScores(matchScores: List<List<Int>>): List<Int> {
    return matchScores.flatten()
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testFlattenTwoLists() {
        val result = flattenScores(listOf(listOf(45, 72), listOf(91, 55)))
        Assert.assertEquals(listOf(45, 72, 91, 55), result)
    }

    @Test
    fun testFlattenThreeLists() {
        val result = flattenScores(listOf(listOf(10), listOf(20, 30), listOf(40)))
        Assert.assertEquals(listOf(10, 20, 30, 40), result)
    }

    @Test
    fun testEmptyInnerLists() {
        val result = flattenScores(listOf(listOf(), listOf(45), listOf()))
        Assert.assertEquals(listOf(45), result)
    }

    @Test
    fun testEmptyOuterList() {
        val result = flattenScores(listOf())
        Assert.assertTrue(result.isEmpty())
    }
}
